<script setup lang="ts">
import{onMounted,ref}from'vue';import{KeyRound,Server,Plus,Wifi,AlertTriangle,Trash2,LockKeyhole}from'lucide-vue-next';import{api}from'../api';import Modal from'../components/Modal.vue';import EmptyState from'../components/EmptyState.vue';
const tab=ref<'keys'|'servers'>('servers'),credentials=ref<any[]>([]),connections=ref<any[]>([]),modal=ref(''),busy=ref<number>(),message=ref(''),error=ref('');const keyForm=ref({name:'',private_key:'',passphrase:''});const emptyConnection=()=>({name:'',host:'',port:22,username:'',auth_type:'key',credential_id:0,password:'',timeout_seconds:10});const connForm=ref(emptyConnection());
async function load(){[credentials.value,connections.value]=await Promise.all([api<any[]>('/api/ssh-credentials'),api<any[]>('/api/ssh-connections')])}
async function saveKey(){error.value='';try{await api('/api/ssh-credentials',{method:'POST',body:JSON.stringify(keyForm.value)});modal.value='';keyForm.value={name:'',private_key:'',passphrase:''};await load()}catch(e:any){error.value=e.message}}
async function saveConnection(){error.value='';try{await api('/api/ssh-connections',{method:'POST',body:JSON.stringify(connForm.value)});modal.value='';connForm.value=emptyConnection();await load()}catch(e:any){error.value=e.message}}
async function test(c:any){busy.value=c.id;message.value='';try{await api(`/api/ssh-connections/${c.id}/test`,{method:'POST'});message.value=`${c.name} 连接成功`}catch(e:any){message.value=e.message}finally{busy.value=undefined}}
async function remove(kind:string,id:number){await api(`/${kind}/${id}`,{method:'DELETE'});await load()}
onMounted(load)
</script>
<template><div class="page-heading"><div><span class="eyebrow">基础资源</span><h1>SSH 资源</h1><p>集中管理工作流使用的服务器连接、密码和共享私钥。</p></div><button class="btn" @click="modal=tab==='keys'?'key':'server'"><Plus/>{{tab==='keys'?'添加私钥':'添加服务器'}}</button></div><div class="notice notice-warning"><AlertTriangle/><div><b>主机密钥校验已关闭</b><p>当前连接无法防御中间人攻击，请仅连接可信网络中的服务器。</p></div></div><div class="tabs"><button :class="{active:tab==='servers'}" @click="tab='servers'"><Server/>服务器连接 <span>{{connections.length}}</span></button><button :class="{active:tab==='keys'}" @click="tab='keys'"><KeyRound/>公用私钥 <span>{{credentials.length}}</span></button></div><p v-if="message" class="toast-inline">{{message}}</p><div v-if="tab==='servers'" class="resource-grid"><article v-for="c in connections" :key="c.id" class="card resource-card"><div class="card-icon"><LockKeyhole v-if="c.auth_type==='password'"/><Server v-else/></div><div class="grow"><h3>{{c.name}}</h3><p>{{c.username}}@{{c.host}}:{{c.port}}</p><small>{{c.auth_type==='password'?'密码认证':'私钥认证'}} · 超时 {{c.timeout_seconds}} 秒</small></div><button class="btn secondary small-btn" :disabled="busy===c.id" @click="test(c)"><Wifi/>{{busy===c.id?'测试中…':'测试'}}</button><button class="icon-btn danger-text" @click="remove('api/ssh-connections',c.id)"><Trash2/></button></article><EmptyState v-if="!connections.length" title="暂无服务器连接" text="可使用密码认证，或先添加公用私钥。"/></div><div v-else class="resource-grid"><article v-for="k in credentials" :key="k.id" class="card resource-card"><div class="card-icon"><KeyRound/></div><div class="grow"><h3>{{k.name}}</h3><p class="mono">{{k.fingerprint}}</p><small>创建于 {{new Date(k.created_at).toLocaleString()}}</small></div><button class="icon-btn danger-text" @click="remove('api/ssh-credentials',k.id)"><Trash2/></button></article><EmptyState v-if="!credentials.length" title="暂无公用私钥" text="私钥将加密保存，明文不会通过接口返回。"/></div><Modal :model-value="modal==='key'" title="添加公用私钥" @update:model-value="modal=''" description="私钥和口令使用服务端主密钥加密保存。"><form @submit.prevent="saveKey"><label>名称<input v-model="keyForm.name" required></label><label>私钥<textarea v-model="keyForm.private_key" required rows="9" placeholder="-----BEGIN OPENSSH PRIVATE KEY-----"></textarea></label><label>口令（可选）<input v-model="keyForm.passphrase" type="password"></label><p v-if="error" class="error">{{error}}</p><div class="panel-actions"><button type="button" class="btn secondary" @click="modal=''">取消</button><button class="btn">保存私钥</button></div></form></Modal><Modal :model-value="modal==='server'" title="添加服务器" @update:model-value="modal=''" description="连接将供 SFTP 上传和 SSH 命令模块使用。"><form @submit.prevent="saveConnection"><label>名称<input v-model="connForm.name" required></label><div class="form-grid"><label>主机<input v-model="connForm.host" required></label><label>端口<input v-model.number="connForm.port" type="number" required></label></div><label>用户名<input v-model="connForm.username" required></label><label>认证方式<select v-model="connForm.auth_type"><option value="key">公用私钥</option><option value="password">密码</option></select></label><label v-if="connForm.auth_type==='key'">认证私钥<select v-model.number="connForm.credential_id" required><option :value="0" disabled>选择私钥</option><option v-for="k in credentials" :key="k.id" :value="k.id">{{k.name}}</option></select></label><label v-else>登录密码<input v-model="connForm.password" type="password" required autocomplete="new-password"><small>密码经 AES-256-GCM 加密保存，接口不会返回。</small></label><label>连接超时（秒）<input v-model.number="connForm.timeout_seconds" type="number" min="1"></label><p v-if="error" class="error">{{error}}</p><div class="panel-actions"><button type="button" class="btn secondary" @click="modal=''">取消</button><button class="btn">保存服务器</button></div></form></Modal></template>
